Object.assign(window.CABINET.categories[0].books[1], {"layout": "exploration", "pages": [{"title": "Latent Fear: Initial Exploration", "image": "latent-fear/early-studies.jpg", "moodImage": "latent-fear/mood-board.jpg", "paragraphs": ["I was exploring how to create an imagined world inspired by childhood memories, dreams, and familiar surroundings, a world that feels both unsettling and comforting.", "Through observation, collage, and experiments with color and form, I gradually realized how ordinary objects in my daily life could become unfamiliar or seemingly alive. These early studies helped me develop the visual atmosphere of Latent Fear."]}]});

window.CABINET.categories[0].books[1].pages.push({"type": "studies", "title": "Final Composition: Combining Two Studies", "bw": "latent-fear/black-white.jpg", "colour": "latent-fear/colour-study.jpg", "markers": "latent-fear/markers.jpg", "gouache": "latent-fear/gouache.jpg", "image": "latent-fear/final-composition.jpg", "artworkTitle": "Beyond Have Remembered", "bwNote": "Black & White: Strong contrast creates unease, as black represents the unseen and unknown.", "colourNotes": ["Gouache: Soft and hazy, like a fading memory.", "Markers: Vibrant, unnatural colours that contrast with childhood memories."], "paragraphs": ["In this final piece, I combined my black and white and colour studies to recreate the atmosphere of my dream.", "I used bright green crayon for the water in the foreground, as its unnatural colour creates a sense of unease. In the background, strong black and white contrast draws attention to a dark, unknown space. I kept the middle ground soft and hazy because, in my dream, my attention was focused on the water and the darkness beyond, leaving everything in between less distinct."]});

window.CABINET.categories[0].books[1].pages.push({"type": "research", "title": "The Familiar and the Unknown", "referenceImage": "latent-fear/research-reference.jpg", "paragraphs": ["Liminal spaces are places of transition, such as corridors and stairways. When they lose their original purpose, they can become unfamiliar and unsettling. Similarly, dreamcore presents distorted versions of familiar places, creating both nostalgia and unease. These images remind us of childhood memories and a past we can no longer return to.", "I also explored the unconscious mind and its connection to dreams. Dreams allow hidden emotions to appear beyond the logic of reality. This led me to surrealism, where familiar objects and unexpected situations come together to create contradictions. Through the works of René Magritte, Joan Miró, and Max Ernst, I discovered how fear can be expressed through unsettling scenes, loneliness, and unnatural forms, rather than obvious danger."], "reflectionTitle": "Personal Reflection", "reflection": ["Through this research, I began to recognize my own fears: the uncertainty of growing older, the gradual loss of self-definition, and the realization that the past I miss no longer exists. These feelings often appear in my dreams, sometimes taking the form of monsters or unfamiliar spaces.", "Rather than directly portraying something frightening, I want to explore the unease created by contradictions and the unknown. In my further development, I hope to understand what I am truly afraid of, and perhaps give these invisible fears a visible form."], "artNotes": ["01 · The Menaced Assassin: Contradiction and death in an ordinary room.", "02 · Harlequin’s Carnival: Loneliness within chaos and celebration.", "03 · The Eye of Silence: Unnatural forms and the feeling of being watched"], "imageTitle": "Liminal Space", "imageCaption": "A familiar place that feels unsettling when its original purpose is lost.", "replacementImages": {"fig2": {"image": "latent-fear/research-miro.jpg", "width": 1539, "height": 1080, "alt": "Harlequin’s Carnival by Joan Miró"}, "fig3": {"image": "latent-fear/research-ernst.png", "width": 2048, "height": 1588, "alt": "The Eye of Silence by Max Ernst"}}});

