Object.assign(window.CABINET.categories[0].books[5], {"layout": "dvd", "height": 195, "width": 36, "symbol": "\u25c9", "subtitle": "A two-disc collection", "pages": [{"title": "Knock Knock", "date": "2024/01/15", "year": "2024", "duration": "", "description": "Knock Knock is a stop-motion animation exploring the fear of the unknown through a handmade miniature room. Wardrobes, screens, boxes, and black fabric conceal what lies within, while food, moving images in a mirror, plants, and ropes suggest an unseen presence. Through these familiar yet unsettling objects, the film explores how uncertainty can turn an ordinary space into something frightening.", "poster": "films/knock-knock.jpg", "videoUrl": "https://drive.google.com/file/d/1QS0V_ur9vhV65im3Tykla8B6NUMbMQzM/view"}, {"title": "Babel of Language", "date": "2026/04/06", "year": "2026", "duration": "", "description": "Babel of Language is an experimental short film that began with a visit to the Museum of Jurassic Technology. Inspired by its strange collection of everyday objects, I went out filming with a friend without a storyboard or a clear plan. Only afterward did I write the narration and bring the footage together.\n\nMoving from billiards to the universe, chance, observation, and the Tower of Babel, the film follows a series of spontaneous associations. It reflects on the limits of human control and understanding, and how language can never fully communicate what we experience, even when we try to understand one another.", "poster": "films/babel-of-language.jpg", "caption": "When the film was exhibited in China, I found myself watching a version of me from the past.", "videoUrl": "https://drive.google.com/file/d/1O5883Iw0-TyM7OBvNWmvy3hyiQ7t6dxX/view"}]});

